#!/usr/bin/env python3
"""Build the editable web/Markdown report from measured tables; no network."""
from pathlib import Path
import json, csv, html, re

R=Path(__file__).resolve().parents[1]
D=json.loads((R/'data/results.json').read_text())
H=[];M=[];TOC=[];fig_no=0
def p(s):
    H.append('<p>'+s+'</p>');M.append(re.sub('<[^>]+>','',s)+'\n')
def eq(s):
    H.append('<div class="eq" dir="ltr">'+html.escape(s)+'</div>');M.append('```text\n'+s+'\n```\n')
def section(id,title):
    if TOC:H.append('</section>')
    TOC.append((id,title));H.append(f'<section id="{id}" class="report-section"><p class="eyebrow">{len(TOC):02} / LAB03</p><h2>{title}</h2>');M.append('\n## '+title+'\n')
def table(caption,heads,rows,small=False):
    H.append('<div class="table-scroll"><table'+(' class="compact"' if small else '')+'><caption>'+caption+'</caption><thead><tr>'+''.join('<th>'+s+'</th>' for s in heads)+'</tr></thead><tbody>')
    M.extend([caption+'\n','| '+' | '.join(heads)+' |','| '+' | '.join(['---']*len(heads))+' |'])
    for row in rows:
        H.append('<tr>'+''.join('<td>'+('<bdi dir="ltr">'+str(s)+'</bdi>' if re.fullmatch(r'[\x00-\x7f\s−±×→≈٪]+',str(s)) else str(s))+'</td>' for s in row)+'</tr>')
        M.append('| '+' | '.join(re.sub('<[^>]+>','',str(s)).replace('|','/') for s in row)+' |')
    H.append('</tbody></table></div>');M.append('')
def fig(path,caption):
    global fig_no
    fig_no+=1
    H.append(f'<figure><a href="{path}" target="_blank" rel="noopener"><img loading="lazy" src="{path}" alt="{html.escape(caption)}"></a><figcaption>شکل {fig_no}. {caption}</figcaption></figure>')
    M.append(f'![{caption}]({path})\n\nشکل {fig_no}. {caption}\n')
def ss(name,cap):fig('assets/screenshots/'+name,cap)
def num(x,dec=1):return '<bdi dir="ltr">'+f'{x:.{dec}f}'+'</bdi>'

