p('در تصویر تنظیم مقایسه با dev برابر ۳۷٫۵ کیلوهرتز، پهنای فیلتر کانال مطابق رابطهٔ دستورکار ۱۰۵ کیلوهرتز است. نسبت <bdi>BL/Bchannel</bdi> برای ۰٫۱۵ حدود ۰٫۳۶ و برای ۰٫۰۸ حدود ۰٫۱۹ خواهد بود. این نسبت توضیح می‌دهد چرا حلقهٔ باریک‌تر نویز خارج از ناحیهٔ تعقیب را کمتر عبور می‌دهد؛ اما مقدار بهینه به انحراف واقعی سیگنال و نیاز به تعقیب مدولاسیون نیز وابسته است.')

section('weak','بخش دوم: کاهش بهره و مقایسهٔ دو آشکارساز')
p('سه تصویر با بهره‌های ۴۰، ۲۷ و ۲۰ دسی‌بل بررسی شدند. ترتیب ارزیابی شنیداری از ثبت قوی به ضعیف، به‌ترتیب «خوب»، «لب مرزی» و «نویز غالب» است. این ارزیابی مربوط به وضعیت شنیده‌شده در هر سطح است؛ برای نتیجه‌گیری دربارهٔ تفاوت دو آشکارساز، از مقایسهٔ طیف‌های هم‌زمان استفاده می‌شود.')
table('جدول ۶ دستورکار — مقایسه در سه سطح سیگنال؛ ترازهای طیفی تقریبی‌اند',['بهره (dB)','توان (dBFS)','پایلوت Q (dB)','نویز Q در 17 kHz','پایلوت PLL (dB)','نویز PLL در 17 kHz','شنیداری'],[[str(r['rf_gain_db']),num(r['channel_power_dbfs'],2),num(r['blue_pilot_db'],0),num(r['blue_noise17_db'],0),num(r['red_pilot_db'],0),num(r['red_noise17_db'],0),r['quality']] for r in D['weak_signal']],True)
table('کنتراست پایلوت نسبت به کف محلی؛ از تفاضل دو ستون هم‌واحد جدول ۶',['بهره (dB)','Q: پایلوت − نویز (dB)','PLL: پایلوت − نویز (dB)','تفسیر'],[[str(r['rf_gain_db']),num(r['blue_pilot_margin_db'],1),num(r['red_pilot_margin_db'],1),s] for r,s in zip(D['weak_signal'],['پایلوت در هر دو مسیر مشخص است','پایلوت PLL نسبت به کف محلی مشخص‌تر است','در تمایزگر نزدیک کف؛ در PLL نیز کم‌کنتراست'])],True)
p('در سطح ۲۷ دسی‌بل، کنتراست پایلوت حدود ۴٫۱ دسی‌بل برای تمایزگر و ۷٫۸ دسی‌بل برای PLL به دست آمد؛ برتری تقریبی PLL در این شاخص حدود ۳٫۷ دسی‌بل است. در سطح ۲۰ دسی‌بل، قلهٔ تمایزگر تقریباً در کف نویز قرار می‌گیرد و خوانش آن صرفاً کنتراست ظاهری حدود ۲ دسی‌بل دارد. نتیجهٔ شنیداری این سطح، نویز غالب بود. بدین ترتیب، کاهش نویز طیفی PLL در دریافت ضعیف دیده می‌شود، ولی در سطح بسیار ضعیف برای بازیابی مفید صدا کافی نیست.')
p('عددهای پایلوت منهای کف، شاخص مقایسهٔ همان FFT هستند؛ SNR انتگرالی صوت یا نسبت توان کل پایلوت به نویز با پهنای باند مشخص نیستند. تفاضل هم‌زمان دو منحنی و یکسان‌بودن پنجرهٔ FFT، آن‌ها را برای مقایسهٔ نسبی مناسب می‌کند. چون با کاهش بهره، سهم نویز طبقات بعدی و ADC نسبت به سیگنال ورودی بیشتر می‌شود، کاهش بهره الزاماً مانند یک تضعیف‌گر ایده‌آلِ پیش از گیرنده رفتار نمی‌کند.')
ss('Part2_3_gain_27.png','ثبت لب مرزی در بهرهٔ ۲۷ دسی‌بل: خط پایلوت در PLL با وجود تراز مطلق کمتر، نسبت به کف محلی بهتر از تمایزگر دیده می‌شود.')
fig('figures/pilot_margin.png','روند کنتراست پایلوت در سه بهره. در پایین‌ترین سطح، قلهٔ آبی نزدیک کف است و عدد آن باید به‌صورت خوانش ظاهری تفسیر شود.')

section('cable','بخش سوم: پیوند کابلی و بازیابی تک‌تن')
p('در فرستنده، فرکانس ۴۳۴ مگاهرتز، تضعیف ۷۰ دسی‌بل، انحراف ۵ کیلوهرتز و دامنهٔ دیجیتال ۰٫۵ در تصاویر دیده می‌شود. برای تن ۱ کیلوهرتز، شاخص مدولاسیون ۵ است و خطوط RF با فاصلهٔ ۱ کیلوهرتز ظاهر می‌شوند. با تغییر تن به ۳ کیلوهرتز و ثابت‌ماندن انحراف، شاخص به ۱٫۶۶۷ می‌رسد و فاصلهٔ خطوط سه برابر می‌شود. در طیف صوت بازیابی‌شده نیز جفت قلهٔ متناظر در دو سوی صفر دیده می‌شود.')
ss('Part3_7_fm=1000_dev=5000_tx.png','تنظیمات و طیف فرستنده: تن ۱ کیلوهرتز، انحراف ۵ کیلوهرتز، تضعیف ۷۰ دسی‌بل و دامنهٔ ۰٫۵.')
p('در ثبت تنظیم گیرندهٔ پیوند، dev برابر ۷۵ کیلوهرتز و پهنای صوتی ۱۵ کیلوهرتز دیده می‌شود؛ این dev گیرنده با انحراف واقعی ۵ کیلوهرتزی فرستنده دو کمیت جدا هستند. اولی مقیاس آشکارساز و فیلتر گیرنده را تعیین می‌کند و دومی شاخص مدولاسیون و طیف ارسالی را. تنظیم ریز در این تصویر ۲ هرتز است و SINAD آن ۳۴٫۲۸ دسی‌بل خوانده می‌شود. ثبت هم‌زمان بعدی در Part3_5، مقدار SINAD برابر ۳۴٫۲۰ دسی‌بل را نشان می‌دهد.')
table('توان و کیفیت پیوند در ثبت‌های بخش سوم',['کمیت','مقدار','مرجع'],[
 ['توان پیش از روشن‌شدن سیگنال','−78.250565 dBFS','Part3_3_rxPower.png'],
 ['توان با سیگنال','−47.432655 dBFS','Part3_5.png'],
 ['اختلاف تراز کل / نویز','30.817910 dB','محاسبه از دو عدد بالا'],
 ['CNR با تفریق خطی','30.814311 dB','با فرض تنظیم مشترک دو قرائت'],
 ['SINAD هم‌زمان با طیف','34.196014 dB','Part3_5.png']])
eq('CNR = 10 log10[10^(30.817910/10) − 1] = 30.8143 dB')
p('این CNR مربوط به نوار مشترک اندازه‌گیری در این ثبت‌هاست؛ عدد به نوار ۱۶ کیلوهرتزی مرجع NBFM تبدیل نشده است. تضعیف واقعی فرستنده در تصاویر ۷۰ دسی‌بل است، بنابراین مقدار نیز به همین تنظیم مربوط است. SINAD نسبت توان کل صوت به توان باقی‌مانده پس از حذف تن است؛ به علت بهرهٔ پردازشی FM و تفاوت پهنای باند، برابرنبودن آن با CNR ورودی طبیعی است.')
ss('Part3_5.png','طیف کانال همراه با توان −۴۷٫۴۳۲۶۵۵ dBFS و SINAD حدود ۳۴٫۲۰ dB در ثبت پیوند.')

section('bandwidth','بخش سوم: پهنای باند و صفرشدن حامل')
p('معیار خواسته‌شده در جدول ۷، فاصلهٔ بیرونی‌ترین خطوطی است که حداکثر ۲۰ دسی‌بل از قوی‌ترین خط پایین‌ترند. این پهنا با B99 یکسان تعریف نمی‌شود: اولی آستانهٔ ارتفاع خط است، درحالی‌که دومی ۹۹ درصد توان تجمعی را در بر می‌گیرد. برای استخراج از تصویر، تراز قوی‌ترین خط در هر قاب صفر شده و خطوط داخل آستانه شناسایی شده‌اند.')
table('جدول ۷ — پهنای طیف و مقایسه با کارسون؛ Δf = 5 kHz',['fm (kHz)','β','کارسون (kHz)','طیف −20 dB (kHz)','اختلاف با کارسون','B99 نظری بسل (kHz)'],[[str(r['fm_hz']/1000),num(r['beta'],3),str(r['B_carson_hz']/1000),str(r['B20_screenshot_hz']/1000),num(100*(r['B20_screenshot_hz']/r['B_carson_hz']-1),1)+'٪',str(r['B99_bessel_theory_hz']/1000)] for r in D['bandwidth']],True)
p('برای تن ۱ کیلوهرتز، خطوط مرتبهٔ ±۷ هنوز در آستانهٔ ۲۰ دسی‌بل قرار می‌گیرند، بنابراین پهنای خوانده‌شده حدود ۱۴ کیلوهرتز است. برای تن ۳ کیلوهرتز، خطوط مرتبهٔ ±۳ در آستانه قرار دارند و پهنا حدود ۱۸ کیلوهرتز می‌شود. کارسون در این دو مقایسهٔ آستانه‌ای به‌ترتیب ۲ کیلوهرتز، یا ۱۶٫۷ و ۱۲٫۵ درصد، کمتر برآورد می‌کند. از نظر درصد، اختلاف حالت ۱ کیلوهرتز بیشتر است؛ این اختلاف با توجه به متفاوت‌بودن معیارها تفسیر می‌شود.')
fig('figures/measured_sidebands.png','نمودار ساخته‌شده از خوانش پیکسل‌های طیف واقعی فرستنده. خط‌چین آستانهٔ −۲۰ دسی‌بل و ناحیهٔ رنگی پهنای کارسون است؛ منحنی شبیه‌سازی جایگزین داده نشده است.')
p('برای مقایسهٔ مستقل نظری، توان خطوط FM تک‌تن با <bdi>Jₙ²(β)</bdi> محاسبه شد. شرط زیر، کوچک‌ترین N لازم برای پوشاندن ۹۹ درصد توان را می‌دهد. برای β برابر ۵، N برابر ۶ و B99 نظری برابر ۱۲ کیلوهرتز است؛ برای β برابر ۵/۳، N برابر ۳ و B99 نظری برابر ۱۸ کیلوهرتز به دست می‌آید. در نتیجه در حالت دوم، کارسون از B99 نظری نیز ۱۲٫۵ درصد کمتر است. B99 اندازه‌گیری‌شده از IQ در بخش تحلیل تکمیلی ثبت می‌شود.')
eq('J₀²(β) + 2 Σ[n=1..N] Jₙ²(β) ≥ 0.99     ;     B99,theory = 2 N fm')
p('در روش کالیبراسیون صفر حامل، دامنهٔ مؤلفهٔ مرکزی متناسب با <bdi>J₀(β)</bdi> است؛ دو ریشهٔ اول آن ۲٫۴۰۴۸۲۶ و ۵٫۵۲۰۰۷۸ هستند. با ثابت‌بودن تن در ۱ کیلوهرتز، انحراف‌های مرجع زیر حاصل می‌شوند. صفرشدن حامل به معنی حذف همهٔ توان FM نیست؛ توان به خطوط جانبی منتقل می‌شود.')
table('مرجع نظری کالیبراسیون انحراف؛ fm = 1 kHz',['صفر J0','β نظری','انحراف نظری (Hz)','مقدار گرد‌شدهٔ مرجع (Hz)'],[['اول','2.4048256','2404.8256','2405'],['دوم','5.5200781','5520.0781','5520']])
p('تصاویر با برچسب‌های ۲۴۰۵ و ۵۵۲۰ در مجموعهٔ جلسه، طیف صوت و خروجی آشکارساز را نمایش می‌دهند؛ در آن‌ها جفت قلهٔ صوتی نزدیک همین فرکانس‌ها دیده می‌شود. ملاک تعیین صفر J0، مؤلفهٔ مرکزی طیف RF پیش از آشکارساز در حالی است که fm ثابت مانده و dev جاروب می‌شود. بنابراین مقدارهای بالا به‌عنوان مرجع نظری کالیبراسیون ثبت شده‌اند و با جابه‌جایی قلهٔ صوت یکی گرفته نمی‌شوند.')
p('تفکیک خانه‌های FFT در نرخ ۲۴۰ کیلوهرتز و طول ۴۰۹۶، حدود ۵۸٫۵۹ هرتز است. خطای گردکردن تنظیم انحراف به مقادیر صحیح ۲۴۰۵ و ۵۵۲۰، به‌ترتیب +۰٫۱۷۴۴ و −۰٫۰۷۸۱ هرتز خواهد بود؛ این‌ها خطای گردکردن مرجعند. برای برآورد اثر تشخیص «صفر»، اگر حد آشکارسازی دامنهٔ حامل ۱٪ دامنهٔ کل باشد، با تقریب <bdi>J₀(β)≈−J₁(β₀)δβ</bdi>، بازهٔ انحراف تقریباً ±۱۹٫۳ هرتز در صفر اول و ±۲۹٫۴ هرتز در صفر دوم است. این دو عدد سناریوی حساسیت با آستانهٔ اعلام‌شده‌اند، نه عدم قطعیت تجربی ادعاشده.')

section('questions','پاسخ پرسش‌های ۱ تا ۶ دستورکار')
for title,answer in [
 ('پرسش ۱ — نصف‌کردن dev چه اثری دارد؟','ضریب آشکارساز معکوس dev است؛ نصف‌کردن آن دامنهٔ خروجی را دو برابر و تراز را ۶٫۰۲ دسی‌بل بیشتر می‌کند. RF فرستاده‌شده ثابت است. در پیاده‌سازی حاضر فیلتر کانال هم به dev وابسته است؛ به همین دلیل باید طیف ورودی پیش از فیلتر را از طیف خروجی فیلتر جدا کرد.'),
 ('پرسش ۲ — چرا خطای فرکانس به شکل مقدار ثابت ظاهر می‌شود؟','آفست ثابت به فاز، جملهٔ خطی ۲πδft اضافه می‌کند و مشتق فاز آن ثابت است. مقدار خوانده‌شدهٔ این جلسه، معادل ظاهری +۱۴٫۱۸ ppm در ۹۰ مگاهرتز است. گزارش آزمایش اول سایت، برآورد مشروط FCCH حدود −۲٫۱۸ ppm را آورده است [۵]؛ این دو عدد در علامت و اندازه یکسان نیستند. چون روش مرجع، باند فرکانسی و شرایط دو آزمون متفاوت است، نتیجهٔ FM را به‌صورت آفست ظاهری همان ایستگاه گزارش می‌کنیم و آن را تأیید عددی کالیبراسیون قبلی نمی‌دانیم.'),
 ('پرسش ۳ — چرا PLL باریک مؤلفه‌های ۳۸ و ۵۷ کیلوهرتز را تضعیف می‌کند؟','حلقه فقط تغییرات فاز و فرکانسی را که در محدودهٔ تعقیب زمانی آن قرار می‌گیرند دنبال می‌کند. مؤلفه‌های بالاتر سریع‌ترند و با باریک‌شدن حلقه زودتر تضعیف می‌شوند. باریک‌کردن بیشتر در نهایت خود صوت را نیز دچار اعوجاج می‌کند؛ افت کیفیت از ۰٫۰۸ به پایین با این سازوکار سازگار است.'),
 ('پرسش ۴ — پایلوت به نویز در سیگنال ضعیف برای کدام بهتر بود؟','در ثبت بهرهٔ ۲۷ دسی‌بل، شاخص پایلوت منهای کف محلی برای PLL حدود ۷٫۸ و برای تمایزگر ۴٫۱ دسی‌بل بود. PLL در این شاخص حدود ۳٫۷ دسی‌بل برتری داشت. کاهش نسبت پهنای حلقه به پهنای کانال سهم نویز خروجی را کم می‌کند؛ حلقه باید هم‌زمان به اندازهٔ کافی برای دنبال‌کردن پیام پهن بماند.'),
 ('پرسش ۵ — اختلاف با صفرهای نظری از کجا می‌آید؟','مرجع نظری برای fm برابر ۱ کیلوهرتز، ۲۴۰۴٫۸۳ و ۵۵۲۰٫۰۸ هرتز است. سهم تنظیم برابر نصف گام مؤثر کنترل dev است؛ مثلاً گام ۵۰ هرتز، سهم کوانتیزهٔ ±۲۵ هرتز دارد. تفکیک FFT برابر ۵۸٫۵۹ هرتز، مقیاس تعیین مکان خط را مشخص می‌کند، اما مستقیماً به همین مقدار خطای dev تبدیل نمی‌شود. تشخیص صفر از کف طیف، با فرض آستانهٔ دامنهٔ ۱٪، حساسیت‌های تقریبی ±۱۹٫۳ و ±۲۹٫۴ هرتز دارد. برای عدم قطعیت نهایی باید گام واقعی جاروب و آستانهٔ تشخیص همان ثبت استفاده شود.'),
 ('پرسش ۶ — کارسون در کدام حالت کمتر برآورد می‌کند؟','در مقایسه با معیار −۲۰ دسی‌بل، هر دو حالت: ۱۲ در برابر ۱۴ کیلوهرتز برای تن ۱ کیلوهرتز و ۱۶ در برابر ۱۸ کیلوهرتز برای تن ۳ کیلوهرتز. در مقایسهٔ ۹۹ درصد توان نظری بسل، حالت ۳ کیلوهرتز مقدار ۱۸ کیلوهرتز دارد و کارسون ۱۲٫۵ درصد کمتر است؛ در حالت ۱ کیلوهرتز B99 نظری ۱۲ کیلوهرتز و برابر کارسون است.')]:
    H.append('<h3>'+title+'</h3>');M.append('### '+title+'\n');p(answer)

